import { FC, PropsWithChildren, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Badge, Button, ButtonProps, Modal, type ModalProps } from 'antd';

import FiltersIcon from 'assets/images/icons/filters.svg?react';
import { useStateFilters } from 'features/Filters/hooks/useStateFilters';
import { useMedia } from 'shared/hooks';

import styles from './ExtendedFiltersWrapper.module.scss';

interface IExtendedFiltersWrapperProps {
	appliedFiltersCount?: number;
	applyFilters: ReturnType<typeof useStateFilters>['applyFilters'];
	btnProps?: ButtonProps;
	clearFilters: ReturnType<typeof useStateFilters>['clearFilters'];
	modalProps?: ModalProps;
	onClose?: () => void;
	onOpen?: () => void;
}

export const ExtendedFiltersWrapper: FC<PropsWithChildren<IExtendedFiltersWrapperProps>> = ({
	appliedFiltersCount,
	applyFilters,
	btnProps,
	children,
	clearFilters,
	modalProps,
	onClose,
	onOpen,
}) => {
	const { t } = useTranslation();
	const [modalIsOpen, setModalIsOpen] = useState(false);
	const isMobile = useMedia();

	const onOpenModal = () => {
		setModalIsOpen(true);
		onOpen?.();
	};

	const handleOkClick = () => {
		applyFilters();
		setModalIsOpen(false);
		onClose?.();
	};

	const handleResetClick = () => {
		clearFilters();
		setModalIsOpen(false);
		onClose?.();
	};

	return (
		<>
			<Button
				icon={<FiltersIcon />}
				type={isMobile ? 'primary' : 'link'}
				block={isMobile}
				size="large"
				htmlType="button"
				onClick={onOpenModal}
				{...btnProps}>
				{t('Filters')}
				<Badge count={appliedFiltersCount} />
			</Button>
			<Modal
				title={t('All Filters')}
				open={modalIsOpen}
				onCancel={handleOkClick}
				destroyOnHidden
				width={1160}
				footer={
					<div className={styles.extendedFiltersWrapper__buttons}>
						<Button onClick={handleResetClick} htmlType="button">
							{t('Clear filters')}
						</Button>
						<Button type="primary" onClick={handleOkClick} htmlType="button">
							{t('Show results')}
						</Button>
					</div>
				}
				{...modalProps}>
				{children}
			</Modal>
		</>
	);
};
