import { useState } from 'react';

import { useOffersListQuery } from 'entities/Offer';
import { OFFERS_LIMIT } from 'features/Filters';
import { EPaginationParams } from 'features/Pagination';
import { useDebounce } from 'shared/hooks';

export const useOffersSelect = () => {
	const [searchValue, setSearchValue] = useState<string>('');
	const debouncedValue = useDebounce(searchValue, 300);

	const { data, isLoading, isFetching } = useOffersListQuery({
		// eslint-disable-next-line @typescript-eslint/ban-ts-comment
		// @ts-expect-error
		search: debouncedValue || undefined,
		...(!debouncedValue && { [EPaginationParams.LIMIT]: OFFERS_LIMIT }),
	});

	const offersOptions =
		data?.results?.map(({ name, uuid, sources_relations }) => ({
			label: name,
			value: uuid,
			sources: sources_relations.length || null,
		})) || [];

	return {
		isFetching,
		isLoading,
		offersOptions,
		setSearchValue,
	};
};
