import { FC, PropsWithChildren } from 'react';

import { Collapse, type CollapseProps } from 'antd';

import styles from './ExtendedFiltersSection.module.scss';

interface IExtendedFiltersSectionProps {
	title: string;
}

export const ExtendedFiltersSection: FC<PropsWithChildren<IExtendedFiltersSectionProps>> = ({ children, title }) => {
	const items: CollapseProps['items'] = [
		{
			key: '1',
			label: title,
			children: <div className={styles.extendedFiltersSection__body}>{children}</div>,
		},
	];

	return <Collapse defaultActiveKey={['1']} ghost items={items} />;
};
